let j = msg.payload;
if (typeof j === 'string') { try { j = JSON.parse(j); } catch (e) { return null; } }
if (!j || (j.score || 0) < 6) return null;
const why = (j.why || []).slice(0, 6).map(w => '✓ ' + w.text).join('\n');
msg.payload = {
  data: {
    title: 'Centinela ' + (j.regime || '') + ' · ' + j.score + '/10',
    message: (j.title || '') + '\n' + why + '\nNo es consejo financiero.'
  }
};
return msg;
